P=Path(__file__).resolve().parent;c=json.loads((P/'capture.json').read_text());out={'method':'deterministic multistart robust sphere fit to eroded visible mask; geometric approximation, not proof of true fruit center','erosion_pixels':7,'loss':'soft_l1','loss_scale_m':.002,'frames':[]};roi=[(300,270,320,290),(290,360,320,380),(170,200,190,230)];table=[]
