 im=cv2.imread(str(P/f"rgb_{r['index']:02d}.jpg"));d=np.load(P/f"depth_{r['index']:02d}.npy");hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV);mask=cv2.inRange(hsv,(3,90,60),(30,255,255));cs,_=cv2.findContours(mask,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE);cont=max([x for x in cs if cv2.contourArea(x)>2000],key=lambda x:cv2.boundingRect(x)[0]);m=np.zeros(d.shape,np.uint8);cv2.drawContours(m,[cont],-1,255,-1);m=cv2.erode(m,np.ones((7,7),np.uint8));yy,xx=np.where((m>0)&(d>0));z=d[yy,xx]*.001;median=np.median(z);keep=np.abs(z-median)<.08;xx,yy,z=xx[keep][::2],yy[keep][::2],z[keep][::2];k=r['K'];T=np.array(r['camera_to_base']);points=np.c_[(xx-k[2])*z/k[0],(yy-k[5])*z/k[4],z];ray=np.median(points,axis=0);ray=ray/np.linalg.norm(ray);surface=np.median(points,axis=0);fits=[]
 for rad in [.025,.035,.045,.06]:
  init=np.r_[surface+ray*rad,rad];fit=least_squares(lambda x:np.linalg.norm(points-x[:3],axis=1)-x[3],init,loss='soft_l1',f_scale=.002,bounds=(np.r_[surface-.15,.005],np.r_[surface+.15,.12]),max_nfev=300);res=np.linalg.norm(points-fit.x[:3],axis=1)-fit.x[3];base=T@np.r_[fit.x[:3],1];fits.append({'initial_radius_m':rad,'center_base_m':base[:3].tolist(),'radius_m':float(fit.x[3]),'rmse_mm':float(np.sqrt(np.mean(res**2))*1000),'median_abs_residual_mm':float(np.median(np.abs(res))*1000),'p95_abs_residual_mm':float(np.percentile(np.abs(res),95)*1000),'fraction_within_3mm':float(np.mean(np.abs(res)<=.003)),'success':bool(fit.success)})
 rr={'index':r['index'],'points':len(points),'eroded_valid_fraction':float(np.mean(d[m>0]>0)),'fits':fits};out['frames'].append(rr)
