t=np.vstack(table);A=np.c_[t[:,:2],np.ones(len(t))];coef=np.linalg.lstsq(A,t[:,2],rcond=None)[0];out['local_table']={'rois':roi,'coefficients_z_ax_by_c':coef.tolist(),'rmse_mm':float(np.sqrt(np.mean((A@coef-t[:,2])**2))*1000)}
a=np.array([r['fits'][0]['center_base_m'] for r in out['frames']]);rads=np.array([r['fits'][0]['radius_m'] for r in out['frames']]);center=np.median(a,0);surface=np.array(json.loads((P/'contour_localization.json').read_text())['right_target_surface_median_m']);out.update(center_median_m=center.tolist(),center_span_mm=(np.ptp(a,axis=0)*1000).tolist(),radius_range_mm=(np.array([rads.min(),rads.max()])*1000).tolist(),multistart_max_center_span_mm=max(float(np.linalg.norm(np.ptp(np.array([x['center_base_m'] for x in r['fits']]),axis=0))*1000) for r in out['frames']),sphere_center_minus_surface_mm=((center-surface)*1000).tolist(),sphere_bottom_minus_local_table_mm=float((center[2]-np.median(rads)-np.r_[center[:2],1]@coef)*1000))
